/**
 * Embedded licence verification key (Ed25519, SPKI PEM).
 *
 * This file is GENERATED by `npm run license:embed` from
 * `owner-keys/merqo-public.pem`. The private key is never present in this
 * repository, in any installer, or in any release artefact.
 *
 * The committed value below is the MERQO development key used to exercise the
 * activation flow. Before commercial distribution the owner MUST:
 *   1. run the Licence Generator -> "Generate key pair"
 *   2. store the private key in an encrypted, offline location
 *   3. run `npm run license:embed` and rebuild + re-release
 * The build prints a warning when the development key is still in use.
 */
export const EMBEDDED_PUBLIC_KEY_PEM = `-----BEGIN PUBLIC KEY-----
MCowBQYDK2VwAyEAY7T0iP7H+Ul7YdmUgzUWCl7hPd7yxTrF6/vuo54quys=
-----END PUBLIC KEY-----`;

/** Fingerprint of the embedded key (first 16 hex chars of SHA-256 of SPKI DER). */
export const EMBEDDED_KEY_FINGERPRINT = '7242c822d493ab55';

/** Fingerprint of the bundled development key; replaced by the owner's key. */
export const DEV_KEY_FINGERPRINT = '7242c822d493ab55';

/** True while the development key is still embedded (logs a startup warning). */
export const IS_DEVELOPMENT_KEY = EMBEDDED_KEY_FINGERPRINT === DEV_KEY_FINGERPRINT;
